data_types.code:
type User {
  id: ID!
  name: String!
  age: Int
}

while_loop.code:
query GetPage($cursor: String) {
  users(after: $cursor, first: 10) {
    edges { node { name } }
    pageInfo { hasNextPage endCursor }
  }
}

